package com.hbm.client.radar;
import com.hbm.machine.radar.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
@WailaPlugin public final class RadarJadePlugin implements IWailaPlugin{@Override public void register(IWailaCommonRegistration e){e.registerBlockDataProvider(Data.INSTANCE,RadarBlockEntity.class);e.registerBlockDataProvider(Data.INSTANCE,RadarPort.class);}@Override public void registerClient(IWailaClientRegistration e){e.registerBlockComponent(Data.INSTANCE,RadarBlock.class);e.registerBlockComponent(Data.INSTANCE,LargeRadarBlock.class);}private enum Data implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return RadarContent.id("radar_state");}@Override public void appendServerData(CompoundTag tag,BlockAccessor a){var tile=a.getBlockEntity();if(tile instanceof RadarPort port)tile=port.core();if(tile instanceof RadarBlockEntity radar){tag.putInt("hbm:radar_count",radar.entries.size());tag.putBoolean("hbm:radar_jammed",radar.jammed);}}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor a,IPluginConfig c){var tag=a.getServerData();if(tag.contains("hbm:radar_count"))tooltip.add(Component.translatable("jade.hbm.radar.detected",tag.getInt("hbm:radar_count")));if(tag.getBoolean("hbm:radar_jammed"))tooltip.add(Component.translatable("jade.hbm.radar.jammed"));}}}
